std::size_t ui_text_count(UiTextCategory category) noexcept {
    switch (category) {
    case UiTextCategory::TestEnum: return 3;
    case UiTextCategory::PauseReason: return 18;
    case UiTextCategory::SessionType: return 17;
    case UiTextCategory::RuntimeStillStateId: return 9;
    case UiTextCategory::InfoScreenType: return 19;
    case UiTextCategory::TextInfo: return 14;
    case UiTextCategory::TextCommon: return 29;
    case UiTextCategory::TextTime: return 13;
    case UiTextCategory::TextTitle: return 63;
    case UiTextCategory::TextAbout: return 13;
    case UiTextCategory::TextAzure: return 3;
    case UiTextCategory::TextSessions: return 3;
    case UiTextCategory::TextInput: return 4;
    case UiTextCategory::TextPause: return 7;
    case UiTextCategory::TextEeprom: return 8;
    case UiTextCategory::SlideshowAutoCycle: return 4;
    case UiTextCategory::Units: return 2;
    case UiTextCategory::UiCommand: return 176;
    }
    return 0;
}

const char* ui_localized_text(UiTextCategory category, std::uint32_t item, LanguageType language) noexcept {
    const std::uint32_t requested = static_cast<std::uint32_t>(language);
    const std::uint32_t lang = requested < 3 ? requested : 0;
    switch (category) {
    case UiTextCategory::TestEnum: return item < 3 ? TestEnum_text[item][lang] : "<TestEnum::INVALID>";
    case UiTextCategory::PauseReason: return item < 18 ? PauseReason_text[item][lang] : "<PauseReason::INVALID>";
    case UiTextCategory::SessionType: return item < 17 ? SessionType_text[item][lang] : "<SessionType::INVALID>";
    case UiTextCategory::RuntimeStillStateId: return item < 9 ? RuntimeStillStateId_text[item][lang] : "<RuntimeStillStateId::INVALID>";
    case UiTextCategory::InfoScreenType: return item < 19 ? InfoScreenType_text[item][lang] : "<InfoScreenType::INVALID>";
    case UiTextCategory::TextInfo: return item < 14 ? TextInfo_text[item][lang] : "<Text_Info::INVALID>";
    case UiTextCategory::TextCommon: return item < 29 ? TextCommon_text[item][lang] : "<Text_Common::INVALID>";
    case UiTextCategory::TextTime: return item < 13 ? TextTime_text[item][lang] : "<Text_Time::INVALID>";
    case UiTextCategory::TextTitle: return item < 63 ? TextTitle_text[item][lang] : "<Text_Title::INVALID>";
    case UiTextCategory::TextAbout: return item < 13 ? TextAbout_text[item][lang] : "<Text_About::INVALID>";
    case UiTextCategory::TextAzure: return item < 3 ? TextAzure_text[item][lang] : "<Text_Azure::INVALID>";
    case UiTextCategory::TextSessions: return item < 3 ? TextSessions_text[item][lang] : "<Text_Sessions::INVALID>";
    case UiTextCategory::TextInput: return item < 4 ? TextInput_text[item][lang] : "<Text_Input::INVALID>";
    case UiTextCategory::TextPause: return item < 7 ? TextPause_text[item][lang] : "<Text_Pause::INVALID>";
    case UiTextCategory::TextEeprom: return item < 8 ? TextEeprom_text[item][lang] : "<Text_EEPROM::INVALID>";
    case UiTextCategory::SlideshowAutoCycle: return item < 4 ? SlideshowAutoCycle_text[item][lang] : "<SlideshowAutoCycle::INVALID>";
    case UiTextCategory::Units: return item < 2 ? Units_text[item][lang] : "<Units::INVALID>";
    case UiTextCategory::UiCommand: return item < 176 ? UiCommand_text[item][lang] : "<UiCommand::INVALID>";
    }
    return "<UiTextCategory::INVALID>";
}

UiScreenTextResult ui_screen_text(ScreenId screen, LanguageType language, const char*& text) noexcept {
    const std::uint32_t id = static_cast<std::uint32_t>(screen);
    if (id == 0 || id >= 103) return UiScreenTextResult::Unavailable;
    const std::uint32_t lang = static_cast<std::uint32_t>(language);
    if (lang >= 3) return UiScreenTextResult::InvalidLanguage;
    text = screen_text[id - 1][lang];
    return UiScreenTextResult::Ok;
}

const DisplayBitmap* ui_bitmap(UiBitmapId id) noexcept {
    switch (id) {
    case UiBitmapId::LogoLarge: return &LogoLarge_bitmap;
    case UiBitmapId::LogoSmall: return &LogoSmall_bitmap;
    case UiBitmapId::DiagnosticChecker18: return &DiagnosticChecker18_bitmap;
    case UiBitmapId::DiagnosticGradient16: return &DiagnosticGradient16_bitmap;
    case UiBitmapId::DiagnosticChecker16A: return &DiagnosticChecker16A_bitmap;
    case UiBitmapId::DiagnosticChecker16B: return &DiagnosticChecker16B_bitmap;
    case UiBitmapId::DiagnosticBitmap64x32: return &DiagnosticBitmap64x32_bitmap;
    case UiBitmapId::TimeSeparatorLarge: return &TimeSeparatorLarge_bitmap;
    case UiBitmapId::DiagnosticEllipse30x8: return &DiagnosticEllipse30x8_bitmap;
    case UiBitmapId::SelectionSingle: return &SelectionSingle_bitmap;
    case UiBitmapId::DiagnosticEllipse10x8: return &DiagnosticEllipse10x8_bitmap;
    case UiBitmapId::TimeSeparatorSmall: return &TimeSeparatorSmall_bitmap;
    case UiBitmapId::SelectionBullet: return &SelectionBullet_bitmap;
    case UiBitmapId::SelectionUp: return &SelectionUp_bitmap;
    case UiBitmapId::SelectionDown: return &SelectionDown_bitmap;
    case UiBitmapId::SelectionBoth: return &SelectionBoth_bitmap;
    }
    return nullptr;
}
